    18→
    19→// ----------------------------------------------------------------------------
    20→// Phase 0
    21→// ----------------------------------------------------------------------------
    22→
    23→message BeaconState {
    24→  // Versioning [1001-2000]
    25→  uint64 genesis_time = 1001;
    26→  bytes genesis_validators_root = 1002 [ (ethereum.eth.ext.ssz_size) = "32" ];
    27→  uint64 slot = 1003 [
    28→    (ethereum.eth.ext.cast_type) =
    29→        "github.com/OffchainLabs/prysm/v6/consensus-types/primitives.Slot"
    30→  ];
    31→  Fork fork = 1004;
    32→
    33→  // History [2001-3000]
    34→  BeaconBlockHeader latest_block_header = 2001;
    35→  repeated bytes block_roots = 2002
    36→      [ (ethereum.eth.ext.ssz_size) = "block_roots.size" ];
    37→  repeated bytes state_roots = 2003
    38→      [ (ethereum.eth.ext.ssz_size) = "state_roots.size" ];
    39→  repeated bytes historical_roots = 2004 [
    40→    (ethereum.eth.ext.ssz_size) = "?,32",
    41→    (ethereum.eth.ext.ssz_max) = "16777216"
    42→  ];
    43→
    44→  // Eth1 [3001-4000]
    45→  Eth1Data eth1_data = 3001;
    46→  repeated Eth1Data eth1_data_votes = 3002
    47→      [ (ethereum.eth.ext.ssz_max) = "eth1_data_votes.size" ];
    48→  uint64 eth1_deposit_index = 3003;
    49→
    50→  // Registry [4001-5000]
    51→  repeated Validator validators = 4001
    52→      [ (ethereum.eth.ext.ssz_max) = "1099511627776" ];
    53→  repeated uint64 balances = 4002
    54→      [ (ethereum.eth.ext.ssz_max) = "1099511627776" ];
    55→
    56→  // Randomness [5001-6000]
    57→  repeated bytes randao_mixes = 5001
    58→      [ (ethereum.eth.ext.ssz_size) = "randao_mixes.size" ];
    59→
    60→  // Slashings [6001-7000]
    61→  repeated uint64 slashings = 6001
    62→      [ (ethereum.eth.ext.ssz_size) = "slashings.size" ];
    63→
    64→  // Attestations [7001-8000]
    65→  repeated PendingAttestation previous_epoch_attestations = 7001
    66→      [ (ethereum.eth.ext.ssz_max) = "previous_epoch_attestations.max" ];
    67→  repeated PendingAttestation current_epoch_attestations = 7002
    68→      [ (ethereum.eth.ext.ssz_max) = "current_epoch_attestations.max" ];
    69→
    70→  // Finality [8001-9000]
    71→  // Spec type [4]Bitvector which means this would be a fixed size of 4 bits.
    72→  bytes justification_bits = 8001 [
    73→    (ethereum.eth.ext.ssz_size) = "1",
    74→    (ethereum.eth.ext.cast_type) =
    75→        "github.com/prysmaticlabs/go-bitfield.Bitvector4"
    76→  ];
    77→  Checkpoint previous_justified_checkpoint = 8002;
    78→  Checkpoint current_justified_checkpoint = 8003;
    79→  Checkpoint finalized_checkpoint = 8004;
    80→}
    81→
    82→message Fork {
    83→  bytes previous_version = 1 [ (ethereum.eth.ext.ssz_size) = "4" ];
    84→  bytes current_version = 2 [ (ethereum.eth.ext.ssz_size) = "4" ];
    85→  uint64 epoch = 3 [
    86→    (ethereum.eth.ext.cast_type) =
    87→        "github.com/OffchainLabs/prysm/v6/consensus-types/primitives.Epoch"
    88→  ];
    89→}
