    94→  bytes aggregation_bits = 1 [
    95→    (ethereum.eth.ext.ssz_max) = "2048",
    96→    (ethereum.eth.ext.cast_type) =
    97→        "github.com/prysmaticlabs/go-bitfield.Bitlist"
    98→  ];
    99→  AttestationData data = 2;
   100→  // The difference of when attestation gets created and get included on chain.
   101→  uint64 inclusion_delay = 3 [
   102→    (ethereum.eth.ext.cast_type) =
   103→        "github.com/OffchainLabs/prysm/v6/consensus-types/primitives.Slot"
   104→  ];
   105→  // The proposer who included the attestation in the block.
   106→  uint64 proposer_index = 4 [ (ethereum.eth.ext.cast_type) =
   107→                                  "github.com/OffchainLabs/prysm/v6/"
   108→                                  "consensus-types/primitives.ValidatorIndex" ];
   109→}
   110→
   111→message HistoricalBatch {
   112→  repeated bytes block_roots = 1
   113→      [ (ethereum.eth.ext.ssz_size) = "block_roots.size" ];
   114→  repeated bytes state_roots = 2
   115→      [ (ethereum.eth.ext.ssz_size) = "state_roots.size" ];
   116→}
   117→
   118→// The state summary object is defined for summarizing a state
   119→// of a given slot. The summary facilitates regeneration of a
   120→// specific state to allow easy playback using pre-saved state
   121→// and blocks.
   122→message StateSummary {
   123→  // The slot of the state.
   124→  uint64 slot = 1 [
   125→    (ethereum.eth.ext.cast_type) =
   126→        "github.com/OffchainLabs/prysm/v6/consensus-types/primitives.Slot"
   127→  ];
   128→  // The block root of the state.
   129→  bytes root = 2;
   130→}
   131→
   132→message SigningData {
   133→  // The root of the object being signed.
   134→  bytes object_root = 1 [ (ethereum.eth.ext.ssz_size) = "32" ];
   135→  // The domain for the particular object being signed.
   136→  bytes domain = 2 [ (ethereum.eth.ext.ssz_size) = "32" ];
   137→}
   138→
   139→message ForkData {
   140→  // The current version of the fork.
   141→  bytes current_version = 4 [ (ethereum.eth.ext.ssz_size) = "4" ];
   142→  // The genesis validators root of the fork.
   143→  bytes genesis_validators_root = 2 [ (ethereum.eth.ext.ssz_size) = "32" ];
   144→}
   145→
   146→message CheckPtInfo {
   147→  // The randao seed which the check point refers to, this will be used to
   148→  // retrieve shuffled indices.
   149→  bytes seed = 1;
   150→  // The genesis root which the check point refers to. This ensures same seed
   151→  // can't happen on different chain.
   152→  bytes genesis_root = 2;
   153→  // Validators that were active at that check point.
   154→  repeated uint64 active_indices = 3;
   155→  // Validators public keys at that check point.
   156→  repeated bytes pub_keys = 4;
   157→  // The fork data at that check point. This will be used to verify signatures.
   158→  Fork fork = 5;
   159→}
   160→
   161→// DepositMessage serves as a subset of deposit data in order to derive the
   162→// signing root.
   163→message DepositMessage {
   164→  // 48 byte BLS public key of the validator.
   165→  bytes public_key = 1 [
   166→    (ethereum.eth.ext.ssz_size) = "48",
   167→    (ethereum.eth.ext.spec_name) = "pubkey"
   168→  ];
   169→
   170→  // A 32 byte hash of the withdrawal address public key.
   171→  bytes withdrawal_credentials = 2 [ (ethereum.eth.ext.ssz_size) = "32" ];
   172→
   173→  // Deposit amount in gwei.
   174→  uint64 amount = 3;
   175→}
   176→
   177→// PowBlock is a definition from Bellatrix fork choice spec to represent a block
   178→// with total difficulty in the PoW chain. Spec: class PowBlock(Container):
   179→//    block_hash: Hash32
   180→//    parent_hash: Hash32
   181→//    total_difficulty: uint256
   182→message PowBlock {
   183→  bytes block_hash = 1 [ (ethereum.eth.ext.ssz_size) = "32" ];
   184→  bytes parent_hash = 2 [ (ethereum.eth.ext.ssz_size) = "32" ];
   185→  bytes total_difficulty = 3 [ (ethereum.eth.ext.ssz_size) = "32" ];
   186→}
   187→
   188→// ----------------------------------------------------------------------------
   189→// Altair
   190→// ----------------------------------------------------------------------------
   191→
   192→// The beacon state for Altair hard fork 1.
   193→// Reference:
   194→// https://github.com/ethereum/consensus-specs/blob/master/specs/altair/beacon-chain.md#beaconstate
   195→message BeaconStateAltair {
   196→  // Versioning [1001-2000]
