   198→  bytes genesis_validators_root = 1002 [ (ethereum.eth.ext.ssz_size) = "32" ];
   199→  uint64 slot = 1003 [
   200→    (ethereum.eth.ext.cast_type) =
   201→        "github.com/OffchainLabs/prysm/v6/consensus-types/primitives.Slot"
   202→  ];
   203→  Fork fork = 1004;
   204→
   205→  // History [2001-3000]
