   207→  repeated bytes block_roots = 2002
   208→      [ (ethereum.eth.ext.ssz_size) = "block_roots.size" ];
   209→  repeated bytes state_roots = 2003
   210→      [ (ethereum.eth.ext.ssz_size) = "state_roots.size" ];
   211→  repeated bytes historical_roots = 2004 [
   212→    (ethereum.eth.ext.ssz_size) = "?,32",
   213→    (ethereum.eth.ext.ssz_max) = "16777216"
   214→  ];
   215→
   216→  // Eth1 [3001-4000]
   217→  Eth1Data eth1_data = 3001;
   218→  repeated Eth1Data eth1_data_votes = 3002
   219→      [ (ethereum.eth.ext.ssz_max) = "eth1_data_votes.size" ];
   220→  uint64 eth1_deposit_index = 3003;
   221→
   222→  // Registry [4001-5000]
   223→  repeated Validator validators = 4001
   224→      [ (ethereum.eth.ext.ssz_max) = "1099511627776" ];
   225→  repeated uint64 balances = 4002
   226→      [ (ethereum.eth.ext.ssz_max) = "1099511627776" ];
   227→
   228→  // Randomness [5001-6000]
   229→  repeated bytes randao_mixes = 5001
   230→      [ (ethereum.eth.ext.ssz_size) = "randao_mixes.size" ];
   231→
   232→  // Slashings [6001-7000]
   233→  repeated uint64 slashings = 6001
   234→      [ (ethereum.eth.ext.ssz_size) = "slashings.size" ];
   235→
   236→  // Participation [7001-8000]
   237→  bytes previous_epoch_participation = 7001 [
   238→    (ethereum.eth.ext.ssz_max) = "1099511627776"
   239→  ]; // [New in Altair, replaced previous_epoch_attestations]
   240→  bytes current_epoch_participation = 7002 [
   241→    (ethereum.eth.ext.ssz_max) = "1099511627776"
   242→  ]; // [New in Altair, replaced current_epoch_attestations]
   243→
   244→  // Finality [8001-9000]
   245→  // Spec type [4]Bitvector which means this would be a fixed size of 4 bits.
   246→  bytes justification_bits = 8001 [
   247→    (ethereum.eth.ext.ssz_size) = "1",
   248→    (ethereum.eth.ext.cast_type) =
   249→        "github.com/prysmaticlabs/go-bitfield.Bitvector4"
   250→  ];
   251→  Checkpoint previous_justified_checkpoint = 8002;
   252→  Checkpoint current_justified_checkpoint = 8003;
   253→  Checkpoint finalized_checkpoint = 8004;
   254→
   255→  // New Altair fields [9001-10000]
   256→  repeated uint64 inactivity_scores = 9001
   257→      [ (ethereum.eth.ext.ssz_max) = "1099511627776" ]; // [New in Altair]
   258→  SyncCommittee current_sync_committee = 9002;          // [New in Altair]
   259→  SyncCommittee next_sync_committee = 9003;             // [New in Altair]
   260→}
   261→
   262→// SyncCommittee serves as committees to facilitate light client syncing to
   263→// beacon chain.
   264→message SyncCommittee {
   265→  repeated bytes pubkeys = 1
   266→      [ (ethereum.eth.ext.ssz_size) = "sync_committee_bits.size,48" ];
   267→  bytes aggregate_pubkey = 2 [ (ethereum.eth.ext.ssz_size) = "48" ];
   268→}
   269→
   270→// SyncAggregatorSelectionData is used to sign over and then check whether the
   271→// aggregator is selected within a subcommittee.
   272→message SyncAggregatorSelectionData {
   273→  // Slot of this signing data.
   274→  uint64 slot = 1 [
   275→    (ethereum.eth.ext.cast_type) =
   276→        "github.com/OffchainLabs/prysm/v6/consensus-types/primitives.Slot"
   277→  ];
   278→  // Subcommittee index of this signing data.
   279→  uint64 subcommittee_index = 2;
   280→}
   281→
   282→// ----------------------------------------------------------------------------
   283→// Bellatrix
   284→// ----------------------------------------------------------------------------
   285→
   286→message BeaconStateBellatrix {
   287→  // Versioning [1001-2000]
   288→  uint64 genesis_time = 1001;
   289→  bytes genesis_validators_root = 1002 [ (ethereum.eth.ext.ssz_size) = "32" ];
   290→  uint64 slot = 1003 [
   291→    (ethereum.eth.ext.cast_type) =
   292→        "github.com/OffchainLabs/prysm/v6/consensus-types/primitives.Slot"
   293→  ];
   294→  Fork fork = 1004;
   295→
   296→  // History [2001-3000]
   297→  BeaconBlockHeader latest_block_header = 2001;
   298→  repeated bytes block_roots = 2002
   299→      [ (ethereum.eth.ext.ssz_size) = "block_roots.size" ];
   300→  repeated bytes state_roots = 2003

